// Reports any failed LexHive workflow execution to the app's DLQ endpoint.
// The body is raw-signed so the app can verify it byte-for-byte.
const crypto = require('crypto');

const trigger = $json;
const workflowName = trigger.workflow?.name ?? 'unknown-workflow';
const workflowId = trigger.workflow?.id ?? 'unknown';
const executionId = String(trigger.execution?.id ?? 'unknown');
const errorMessage =
  trigger.execution?.error?.message ??
  trigger.error?.message ??
  trigger.error ??
  'n8n workflow execution failed';

const body = {
  source: 'n8n_webhook',
  dedupe_key: `n8n-error:${executionId}`,
  submission_id: '',
  lead_id: '',
  error: `[${workflowName}] ${String(errorMessage).slice(0, 1800)}`,
  attempts: 1,
  payload: {
    workflow_id: workflowId,
    workflow_name: workflowName,
    execution_id: executionId,
    execution_url: trigger.execution?.url ?? null
  }
};

const raw = JSON.stringify(body);
const secret = process.env.N8N_WEBHOOK_SECRET ?? '';
const signature = secret ? crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex') : '';

return [{
  json: {
    raw_body: raw,
    signature: signature ? `sha256=${signature}` : '',
    workflow_name: workflowName,
    execution_id: executionId,
    error: String(errorMessage)
  }
}];
